#include <WiFi.h>
#include <esp_now.h>
#include <esp_wifi.h>

#define FORWARD_BUTTON 13
#define REVERSE_BUTTON 12
#define LEFT_BUTTON    14
#define RIGHT_BUTTON   27
#define STOP_BUTTON    26
#define TURBO_BUTTON   25

#define NORMAL_SPEED 192
#define TURBO_SPEED  255

#define DISCOVERY_INTERVAL 1000
#define COMMAND_INTERVAL 50

unsigned long lastDiscovery = 0;
unsigned long lastCommand = 0;

uint8_t carAddress[6];
bool carFound = false;

struct CommandPacket {
  char command;
  uint8_t speed;
};

bool addCarPeer() {
  if (esp_now_is_peer_exist(carAddress)) {
    return true;
  }

  esp_now_peer_info_t peerInfo = {};
  memcpy(peerInfo.peer_addr, carAddress, 6);
  peerInfo.channel = 1;
  peerInfo.encrypt = false;

  return esp_now_add_peer(&peerInfo) == ESP_OK;
}

void sendCommand(char command, uint8_t speed) {
  if (!carFound) {
    return;
  }

  CommandPacket packet;
  packet.command = command;
  packet.speed = speed;

  esp_now_send(
    carAddress,
    (uint8_t *)&packet,
    sizeof(packet)
  );
}

void onDataReceive(
  const esp_now_recv_info_t *info,
  const uint8_t *data,
  int len
) {
  if (
    len >= 3 &&
    memcmp(data, "CAR", 3) == 0
  ) {
    memcpy(carAddress, info->src_addr, 6);

    if (addCarPeer()) {
      carFound = true;

      Serial.println();
      Serial.println("==============================");
      Serial.println("CAR FOUND");
      Serial.println("CONTROLLER CONNECTED");
      Serial.println("==============================");
    }
  }
}

void searchForCar() {
  uint8_t broadcastAddress[] = {
    0xFF,
    0xFF,
    0xFF,
    0xFF,
    0xFF,
    0xFF
  };

  if (
    !esp_now_is_peer_exist(broadcastAddress)
  ) {
    esp_now_peer_info_t peerInfo = {};

    memcpy(
      peerInfo.peer_addr,
      broadcastAddress,
      6
    );

    peerInfo.channel = 1;
    peerInfo.encrypt = false;

    esp_now_add_peer(&peerInfo);
  }

  const char hello[] = "HELLO";

  esp_now_send(
    broadcastAddress,
    (uint8_t *)hello,
    sizeof(hello)
  );

  Serial.println("Searching for car...");
}

void setup() {
  Serial.begin(115200);

  pinMode(FORWARD_BUTTON, INPUT_PULLUP);
  pinMode(REVERSE_BUTTON, INPUT_PULLUP);
  pinMode(LEFT_BUTTON, INPUT_PULLUP);
  pinMode(RIGHT_BUTTON, INPUT_PULLUP);
  pinMode(STOP_BUTTON, INPUT_PULLUP);
  pinMode(TURBO_BUTTON, INPUT_PULLUP);

  WiFi.mode(WIFI_STA);

  esp_wifi_set_channel(
    1,
    WIFI_SECOND_CHAN_NONE
  );

  Serial.println();
  Serial.println("==============================");
  Serial.println("ESP32 CAR CONTROLLER");
  Serial.println("==============================");

  if (
    esp_now_init() != ESP_OK
  ) {
    Serial.println("ESP-NOW FAILED!");

    while (true) {
      delay(1000);
    }
  }

  esp_now_register_recv_cb(onDataReceive);

  Serial.println("ESP-NOW READY");
  Serial.println("Searching for car...");
}

void loop() {

  // Search for the car
  if (!carFound) {

    if (
      millis() - lastDiscovery >=
      DISCOVERY_INTERVAL
    ) {
      lastDiscovery = millis();

      searchForCar();
    }

    delay(10);

    return;
  }

  // STOP button
  if (
    digitalRead(STOP_BUTTON) == LOW
  ) {

    if (
      millis() - lastCommand >=
      COMMAND_INTERVAL
    ) {
      lastCommand = millis();

      sendCommand('S', 0);

      Serial.println("STOP");
    }

    delay(5);

    return;
  }

  // Default speed = 75%
  uint8_t speed = NORMAL_SPEED;

  // Turbo button = 100%
  if (
    digitalRead(TURBO_BUTTON) == LOW
  ) {
    speed = TURBO_SPEED;
  }

  char command = 'S';

  // Forward
  if (
    digitalRead(FORWARD_BUTTON) == LOW
  ) {
    command = 'F';
  }

  // Reverse
  else if (
    digitalRead(REVERSE_BUTTON) == LOW
  ) {
    command = 'B';
  }

  // Left
  else if (
    digitalRead(LEFT_BUTTON) == LOW
  ) {
    command = 'L';
  }

  // Right
  else if (
    digitalRead(RIGHT_BUTTON) == LOW
  ) {
    command = 'R';
  }

  // No movement button pressed
  else {
    command = 'S';
    speed = 0;
  }

  // Send command
  if (
    millis() - lastCommand >=
    COMMAND_INTERVAL
  ) {

    lastCommand = millis();

    sendCommand(
      command,
      speed
    );

    if (command == 'F') {
      Serial.println("FORWARD");
    }

    else if (command == 'B') {
      Serial.println("REVERSE");
    }

    else if (command == 'L') {
      Serial.println("LEFT");
    }

    else if (command == 'R') {
      Serial.println("RIGHT");
    }
  }

  delay(5);
}
